<?php
require_once __DIR__ . '/../../config/database.php'; require_once __DIR__ . '/../../includes/auth.php'; require_once __DIR__ . '/../../includes/functions.php'; requireAdmin(); $categories = $conn->query('SELECT * FROM categories ORDER BY name ASC'); if ($_SERVER['REQUEST_METHOD'] === 'POST') { $categoryId = (int)($_POST['category_id'] ?? 0); $name = trim($_POST['name'] ?? ''); $description = trim($_POST['description'] ?? ''); $price = (float)($_POST['price'] ?? 0); $stock = (int)($_POST['stock'] ?? 0); $image = trim($_POST['image'] ?? ''); $stmt = $conn->prepare('INSERT INTO products (category_id, name, description, price, stock, image) VALUES (?, ?, ?, ?, ?, ?)'); $stmt->bind_param('issdis', $categoryId, $name, $description, $price, $stock, $image); $stmt->execute(); header('Location: /Web/admin/products/index.php'); exit(); } include __DIR__ . '/../../includes/header.php';
?>
<section class="auth-box"><h2>Thêm sản phẩm</h2><form method="POST" class="auth-form wide"><select name="category_id" required><?php while ($cat = $categories->fetch_assoc()): ?><option value="<?php echo $cat['id']; ?>"><?php echo sanitize($cat['name']); ?></option><?php endwhile; ?></select><input type="text" name="name" placeholder="Tên sản phẩm" required><textarea name="description" placeholder="Mô tả"></textarea><input type="number" step="0.01" name="price" placeholder="Giá" required><input type="number" name="stock" placeholder="Tồn kho" required><input type="text" name="image" placeholder="Tên file ảnh"><button class="btn primary" type="submit">Lưu</button></form></section>
